import{_ as s,o as n,c as t,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"案例 1：把散落的周报整理成台账","description":"","frontmatter":{},"headers":[],"relativePath":"cases/案例1-把散落的周报整理成台账.md","filePath":"cases/案例1-把散落的周报整理成台账.md"}'),o={name:"cases/案例1-把散落的周报整理成台账.md"};function l(i,a,d,p,r,c){return n(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="案例-1-把散落的周报整理成台账" tabindex="-1">案例 1：把散落的周报整理成台账 <a class="header-anchor" href="#案例-1-把散落的周报整理成台账" aria-label="Permalink to &quot;案例 1：把散落的周报整理成台账&quot;">​</a></h1><blockquote><p>难度：⭐ ｜ 场景：文件整理 ｜ 涉及章节：第 3、11 章</p></blockquote><h2 id="场景" tabindex="-1">场景 <a class="header-anchor" href="#场景" aria-label="Permalink to &quot;场景&quot;">​</a></h2><p>你的电脑里散落着 20 多份周报，文件名混乱（<code>周报</code>, <code>weekly</code>, <code>report</code>），放在不同目录。你想把它们整理成一份<strong>统一格式的台账</strong>，还能一眼看出&quot;哪些周有周报、哪些漏了&quot;。</p><h2 id="指令-可直接照做" tabindex="-1">指令（可直接照做） <a class="header-anchor" href="#指令-可直接照做" aria-label="Permalink to &quot;指令（可直接照做）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我的周报散落在 docs/ 和 downloads/ 下，文件名不统一。</span></span>
<span class="line"><span>请帮我：</span></span>
<span class="line"><span>1. 找出所有周报文件（内容包含&quot;周报&quot;或&quot;本周工作&quot;）</span></span>
<span class="line"><span>2. 按周数重新命名（周报-2026-W33.md 这种格式）</span></span>
<span class="line"><span>3. 生成一份台账 index.md，列出：周数、文件名、更新时间、内容摘要（一句话）</span></span>
<span class="line"><span>4. 标出缺失的周（比如第 30 周没有周报）</span></span>
<span class="line"><span>5. 先给我计划，确认后再动手</span></span></code></pre></div><h2 id="我的做法-逐步拆解" tabindex="-1">我的做法（逐步拆解） <a class="header-anchor" href="#我的做法-逐步拆解" aria-label="Permalink to &quot;我的做法（逐步拆解）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① Glob 搜索候选文件（*.md 包含&quot;周报&quot;关键词）</span></span>
<span class="line"><span>② Grep 内容确认：确实包含&quot;本周工作&quot;等特征词</span></span>
<span class="line"><span>③ 列出发现清单：20+ 个文件，分布在 3 个目录</span></span>
<span class="line"><span>④ 提出整理方案（每个文件的新命名和去向）→ 给你确认</span></span>
<span class="line"><span>⑤ 你确认后：重命名 + 汇总摘要</span></span>
<span class="line"><span>⑥ 生成台账 index.md + 缺失周清单</span></span></code></pre></div><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to &quot;交付物&quot;">​</a></h2><ul><li>统一命名的周报文件（<code>周报-2026-W33.md</code> 格式）；</li><li><code>index.md</code> 台账（周数/文件名/更新时间/一句话摘要）；</li><li>缺失周清单（一眼看出哪几周断更了）。</li></ul><h2 id="复盘要点" tabindex="-1">复盘要点 <a class="header-anchor" href="#复盘要点" aria-label="Permalink to &quot;复盘要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>关键点</th></tr></thead><tbody><tr><td>找全</td><td>用&quot;内容特征词&quot;而不是只靠文件名，避免漏掉命名混乱的文件</td></tr><tr><td>摘要</td><td>一句话摘要 = 这篇周报的核心结论，别抄原文</td></tr><tr><td>缺失检测</td><td>台账自动暴露&quot;哪几周没有&quot;，这是整理的隐藏价值</td></tr></tbody></table><h2 id="可复用资产" tabindex="-1">可复用资产 <a class="header-anchor" href="#可复用资产" aria-label="Permalink to &quot;可复用资产&quot;">​</a></h2><ul><li><strong>指令模板</strong>：上面的指令改一下目录和特征词即可复用；</li><li><strong>沉淀建议</strong>：做成&quot;周报台账&quot; Skill，每周自动更新；</li><li><strong>关联章节</strong>：第 11 章（文件整理）、第 17 章（打造 Skill）。</li></ul><p><a href="./">返回案例库</a></p>`,15)])])}const _=s(o,[["render",l]]);export{u as __pageData,_ as default};
